instruction:
Write a pytest test asserting that launching a non-existent command via subprocess raises FileNotFoundError.

import subprocess

def run(cmd):
    return subprocess.run(cmd, capture_output=True)

output:
import json
from jsoncli import main

def test_json_output_parses(capsys):
    assert main(['1', '2', '3']) == 0
    payload = json.loads(capsys.readouterr().out)
    assert payload == {'count': 3, 'sum': 6}

def test_json_output_empty(capsys):
    main([])
    assert json.loads(capsys.readouterr().out) == {'count': 0, 'sum': 0}
